// Module: sub_per
// Description: 64-bit Substitution and Permutation layer
// Standard: IEEE 1364-2001

module sub_per (
    input  wire [63:0] data_i,
    output wire [63:0] data_o
);

    // Internal signal for S-box output
    wire [63:0] sbox_out;

    // S-box definition (4-bit to 4-bit mapping)
    // Using a standard PRESENT-like S-box for demonstration
    function [3:0] sbox_4bit;
        input [3:0] nibble;
        begin
            case (nibble)
                4'h0: sbox_4bit = 4'hC;
                4'h1: sbox_4bit = 4'h5;
                4'h2: sbox_4bit = 4'h6;
                4'h3: sbox_4bit = 4'hB;
                4'h4: sbox_4bit = 4'h9;
                4'h5: sbox_4bit = 4'h0;
                4'h6: sbox_4bit = 4'hA;
                4'h7: sbox_4bit = 4'hD;
                4'h8: sbox_4bit = 4'h3;
                4'h9: sbox_4bit = 4'hE;
                4'hA: sbox_4bit = 4'hF;
                4'hB: sbox_4bit = 4'h8;
                4'hC: sbox_4bit = 4'h4;
                4'hD: sbox_4bit = 4'h7;
                4'hE: sbox_4bit = 4'h1;
                4'hF: sbox_4bit = 4'h2;
                default: sbox_4bit = 4'h0;
            endcase
        end
    endfunction

    // Apply S-box to each 4-bit nibble
    genvar i;
    generate
        for (i = 0; i < 16; i = i + 1) begin : sbox_gen
            assign sbox_out[(i*4)+3 : (i*4)] = sbox_4bit(data_i[(i*4)+3 : (i*4)]);
