// Module: sky130_fd_sc_hd__or4b_4
// Description: 4-input OR gate with one inverted input (D_N)

module sky130_fd_sc_hd__or4b_4 (
    input A,
    input B,
    input C,
    input D_N,
    output X
);

    // Logic tổ hợp: X = A OR B OR C OR (NOT D_N)
    // Sử dụng phép gán liên tục (continuous assignment) để đảm bảo tính chất tổ hợp
    // và tránh tạo ra chốt ẩn (inferred latches).
    assign X = A | B | C | (~D_N);

