```verilog
module gost89_sbox (
    input  [63:0] sbox,
    input  [3:0]  in,
    output reg [3:0] out
);

    // Xử lý logic tổ hợp tra cứu S-box 16-to-1 (64-bit chia thành 16 khối 4-bit)
    // Tránh inferred latch bằng cách gán mặc định và dùng cú pháp part-select động.
    always @(*) begin
        case (in)
            4'h0:    out = sbox[3:0];
            4'h1:    out = sbox[7:4];
            4'h2:    out = sbox[11:8];
            4'h3:    out = sbox[15:12];
            4'h4:    out = sbox[19:16];
            4'h5:    out = sbox[23:20];
            4'h6:    out = sbox[27:24];
            4'h7:    out = sbox[31:28];
            4'h8:    out = sbox[35:32];
            4'h9:    out = sbox[39:36];
            4'hA:    out = sbox[43:40];
            4'hB:    out = sbox[47:44];
            4'hC:    out = sbox[51:48];
            4'hD:    out = sbox[55:52];
            4'hE:    out = sbox[59:56];
            4'hF:    out = sbox[63:60];
            default: out = 4'h0;
