        4'd4:    seg_7 = 7'b0110011;
        4'd5:    seg_7 = 7'b1011011;
        4'd6:    seg_7 = 7'b1011111;
        4'd7:    seg_7 = 7'b1110000;
        4'd8:    seg_7 = 7'b1111111;
        4'd9:    seg_7 = 7'b1111011;
