   - Trạng thái gồm: `IDLE`, `CONVERT`, `DONE`.
   - Sử dụng phép gán non-blocking `<=` trong khối `always @(posedge clk or posedge rst)` và blocking `=` trong khối tổ hợp `always @(*)`.
   - Triệt tiêu hoàn toàn Inferred Latch bằng cách định nghĩa đầy đủ các nhánh `if-else` và `default` trong câu lệnh `case`.

### Mã nguồn RTL Verilog (IEEE 1364-2001):

```verilog
module bin_to_dec_converter (
    input  wire clk,
    input  wire rst,
    input  wire set,
    output reg  overflow
);

    // Định nghĩa các trạng thái FSM
    parameter IDLE    = 2'b00;
    parameter CONVERT = 2'b01;
    parameter DONE    = 2'b10;

    reg [1:0] current_state, next_state;
    reg [7:0] binary_val;
    reg [3:0] tens;
    reg [3:0] ones;

    // Khối tuần tự: Cập nhật trạng thái và thanh ghi
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            current_state <= IDLE;
            binary_val    <= 8'd0;
            tens          <= 4'd0;
            ones          <= 4'd0;
            overflow      <= 1'b0;
        end else begin
            current_state <= next_state;
            if (set) begin
                binary_val <= 8'd150; // Giá trị mẫu vượt quá 99 để test overflow
                tens       <= 4'd0;
                ones       <= 4'd0;
                overflow   <= 1'b0;
            end else if (current_state == CONVERT) begin
                if (binary_val >= 8'd100) begin
                    overflow <= 1'b1;
                end else begin
                    overflow <= 1'b0;
                    if (binary_val >= 8'd10) begin
                        tens       <= tens + 1'b1;
                        binary_val <= binary_val - 8'd10;
                    end else begin
                        ones       <= binary_val[3:0];
                        binary_val <= 8'd0;
                    end
                end
            end
        end
    end

    // Khối tổ hợp: Xác định chuyển mạch trạng thái
    always @(*) begin
        next_state = current_state;
        case (current_state)
            IDLE: begin
                if (set) begin
                    next_state = CONVERT;
                end
            end
            CONVERT: begin
                if (binary_val < 8'd10 || binary_val >= 8'd100) begin
                    next_state = DONE;
                end else begin
                    next_state = CONVERT;
                end
            end
            DONE: begin
                if (set) begin
                    next_state = CONVERT;
                end else begin
                    next_state = DONE;
                end
            end
            default: begin
                next_state = IDLE;
            end
        endcase
    end

endmodule
```

### Phân tích kiến trúc vi mạch (Teacher CoT):
1. **Phân tích lỗi từ Linter:** 
   - Lỗi được báo: `NONBLOCKING_IN_COMBINATIONAL` hoặc sử dụng nhầm cú pháp gán bên trong các cấu trúc tổ hợp/generate. Thực tế, mã trước đó sử dụng cú pháp `generate/for` với lệnh `assign` (hoàn toàn hợp lệ), nhưng có sự nhầm lẫn trong một số phiên bản trình dịch khi trộn lẫn biến vòng lặp hoặc các đoạn code nháp bên trên (`always @(*)` với lỗi gán thiếu `assign` như `p0 = in1 ^ in2;`).
   - Để triệt tiêu hoàn toàn lỗi linter, ta thiết kế lại mạch Kogge-Stone 15-bit hoàn toàn bằng các câu lệnh `assign` kết hợp khối `generate` chuẩn mực của Verilog-2001, tránh hoàn toàn các khối `always @(*)` phức tạp chứa vòng lặp `for` hay gán sai cú pháp.

2. **Cấu trúc Kogge-Stone Adder 15-bit:**
   - **Level 0 (Base Generate & Propagate):** 
     - $G_0[i] = A[i] \cdot B[i]$
     - $P_0[i] = A[i] \oplus B[i]$
   - **Các tầng Prefix (Level 1, 2, 3, 4 ứng với khoảng cách bước nhảy 1, 2, 4, 8):**
     - Sử dụng Black/Gray cells qua các tầng `generate` để tính toán song song các tín hiệu Generate ($G$) và Propagate ($P$).
   - **Khâu tính toán Carry (C):**
     - $C[0] = 0$
     - $C[i] = G_{final}[i-1]$ với $i = 1 \dots 15$.
     - $C[15] = G_{final}[14]$ (chính là `cout`).
   - **Khâu tính Sum:**
     - $Sum[i] = P_0[i] \oplus C[i]$

3. **Đảm bảo không có Latch / Dangling Pin:**
   - Tất cả các ngõ ra `sum` và `cout` đều được gán tường minh. Các ngõ vào `in1`, `in2` đều tham gia tích cực vào tầng cơ sở $G_0, P_0$.

```verilog
module kogge_stone_15 (
    input  [14:0] in1,
    input  [14:0] in2,
    output [14:0] sum,
    output        cout
);

    // Level 0: Generate and Propagate
    wire [14:0] G0, P0;
    assign G0 = in1 & in2;
    assign P0 = in1 ^ in2;

    // Level 1 (dist = 1)
    wire [14:0] G1, P1;
    assign G1[0] = G0[0];
    assign P1[0] = P0[0];

    genvar i1;
    generate
        for (i1 = 1; i1 < 15; i1 = i1 + 1) begin : level1
            assign G1[i1] = G0[i1] | (P0[i1] & G0[i1-1]);
            assign P1[i1] = P0[i1] & P0[i1-1];
        end
    endgenerate

    // Level 2 (dist = 2)
    wire [14:0] G2, P2;
    assign G2[1:0] = G1[1:0];
    assign P2[1:0] = P1[1:0];

    genvar i2;
    generate
        for (i2 = 2; i2 < 15; i2 = i2 + 1) begin : level2
            assign G2[i2] = G1[i2] | (P1[i2] & G1[i2-2]);
            assign P2[i2] = P1[i2] & P1[i2-2];
        end
    endgenerate

    // Level 3 (dist = 4)
    wire [14:0] G3, P3;
    assign G3[3:0] = G2[3:0];
    assign P3[3:0] = P2[3:0];

    genvar i3;
    generate
        for (i3 = 4; i3 < 15; i3 = i3 + 1) begin : level3
            assign G3[i3] = G2[i3] | (P2[i3] & G2[i3-4]);
            assign P3[i3] = P2[i3] & P2[i3-4];
        end
    endgenerate

    // Level 4 (dist = 8)
    wire [14:0] G4, P4;
    assign G4[7:0] = G3[7:0];
    assign P4[7:0] = P3[7:0];

    genvar i4;
    generate
        for (i4 = 8; i4 < 15; i4 = i4 + 1) begin : level4
            assign G4[i4] = G3[i4] | (P3[i4] & G3[i4-8]);
            assign P4[i4] = P3[i4] & P3[i4-8];
        end
    endgenerate

    // Carry vector generation
    wire [15:0] C;
    assign C[0] = 1'b0;

    genvar ic;
    generate
        for (ic = 1; ic <= 15; ic = ic + 1) begin : carry_gen
            assign C[ic] = G4[ic-1];
        end
    endgenerate

    // Final Sum and Carry-out
    assign sum  = P0 ^ C[14:0];
    assign cout = C[15];

endmodule
```

### Phân tích kiến trúc vi mạch (Teacher CoT):
1. **Chức năng I/O và độ rộng bit:**
   - `A [3:0]`: Toán hạng thứ nhất (4-bit, input).
   - `B [3:0]`: Toán hạng thứ hai (4-bit, input).
   - `C_in`: Cờ điều khiển phép tính/mức nhớ vào (1-bit, input). Khi `C_in = 0`, mạch thực hiện phép cộng ($A + B$). Khi `C_in = 1`, mạch thực hiện phép trừ ($A - B$) sử dụng bù 2.
   - `S [3:0]`: Kết quả 4-bit (output).
   - `Cout`: Cờ nhớ ra/tràn (1-bit, output).

2. **Cấu trúc tổ hợp:**
   - Để thực hiện cả cộng và trừ, đầu vào `B` được đảo bit (XOR với `C_in`) và `C_in` được cộng thêm vào như là bit nhớ ban đầu.
   - Ta có thể thực hiện phép tính bằng cách mở rộng dữ liệu lên 5 bit để tính chính xác `Cout` và kết quả 4-bit: 
     $$\{{Cout, S\}} = A + (B \oplus \{4\{C_in\}\}) + C\_in$$.
   - Toàn bộ thiết kế là mạch tổ hợp thuần túy, sử dụng khối `always @(*)` với phép gán blocking `=` để tránh chốt ẩn (inferred latch) và hiện tượng chạy đua (race condition).

```verilog
module bit4_adder_sub (
    input  [3:0] A,
    input  [3:0] B,
    input        C_in,
    output [3:0] S,
    output       Cout
);

    // Tín hiệu trung gian mở rộng 5-bit để chứa kết quả và carry-out
    wire [4:0] result;

    // Khi C_in = 1, đảo B (B ^ {4{1'b1}}) và cộng thêm C_in (1) để tạo bù 2.
    // Khi C_in = 0, giữ nguyên B và cộng 0.
    wire [3:0] b_xor;

    assign b_xor = B ^ {4{C_in}};
    assign result = {1'b0, A} + {1'b0, b_xor} + {4'b0000, C_in};

    assign S = result[3:0];
    assign Cout = result[4];

endmodule
```

### Phân tích kiến trúc vi mạch (Teacher CoT):
1. **Chức năng I/O & Độ rộng bit:**
   - `qout` [31:0] (Input): Dữ liệu 32-bit thứ nhất.
   - `qout_b` [31:0] (Input): Dữ liệu 32-bit thứ hai.
   - `clk` [0:0] (Input): Tín hiệu xung nhịp hệ thống.
   - `eout` [5:0] (Output): Kết quả ngõ ra 6-bit sau khi qua cây gộp (fat tree) giảm số bit.

2. **Cấu trúc & Luồng dữ liệu (Dataflow):**
   - **Bước 1 (Tổ hợp / Kết hợp):** Tính toán phép NAND đảo bit giữa hai vector 32-bit `qout` và `qout_b`. Ta thu được kết quả 32-bit hoặc gộp lại tạo thành chuỗi 64-bit NAND tùy theo đặc tả ("computes a 64-bit NAND of two 32-bit inputs"). Cụ thể, mỗi cặp bit tương ứng hoặc toàn bộ: ở đây ta thực hiện phép toán bitwise kết hợp, ví dụ mở rộng thành 64-bit bằng cách lấy `~(qout & qout_b)` kết hợp với các biến đổi logic, hoặc đơn giản là thanh ghi lưu trữ kết quả trung gian 64-bit từ `{~(qout & qout_b), (qout ^ qout_b)}` hoặc tương đương để đảm bảo đủ 64-bit đầu vào cho cây gộp (fat tree). Để chuẩn xác theo mô tả "64-bit NAND", ta tạo ra bus 64-bit gồm `qout` và `qout_b` đảo (ví dụ: `[31:0] ~qout` và `[31:0] ~qout_b` ghép lại thành 64-bit).
   - **Bước 2 (Tuần tự - Register):** Lưu trữ kết quả 64-bit này vào một thanh ghi kích hoạt bằng cạnh lên của `clk` (`posedge clk`) để triệt tiêu Race Condition.
   - **Bước 3 (Fat Tree Reduction / Tổ hợp):** Dùng cấu trúc cây (fat tree) nén/gộp 64-bit xuống còn 6-bit (ví dụ: thông qua các tầng XOR/ADD cây nhị phân hoặc đếm số bit 1 - population count / XOR reduction tree) để tạo ra ngõ ra `eout` [5:0]. Không có chốt ẩn (inferred latch) vì mọi đường đi tổ hợp đều được gán đầy đủ.

```verilog
module adc_digi_top (
    input  [31:0] qout,
    input  [31:0] qout_b,
    input         clk,
    output [5:0]  eout
);

// Bước 1 & 2: Tạo chuỗi 64-bit từ NAND/Logic của 2 input và đăng ký bằng thanh ghi (Register)
reg [63:0] nand_reg;

always @(posedge clk) begin
    // Tạo chuỗi 64-bit kết hợp NAND giữa qout và qout_b
    nand_reg <= { ~(qout & qout_b), ~(qout | qout_b) };
end

// Bước 3: Cây gộp (Fat Tree) 64-bit về 6-bit eout
// Sử dụng phép cộng dồn cây nhị phân (popcount / reduction tree)
wire [6:0] sum_stage1 [31:0];
wire [7:0] sum_stage2 [15:0];
wire [8:0] sum_stage3 [7:0];
wire [9:0] sum_stage4 [3:0];
wire [10:0] sum_stage5 [1:0];
wire [11:0] sum_final;

genvar i;
generate
    for (i = 0; i < 32; i = i + 1) begin : gen_s1
        assign sum_stage1[i] = nand_reg[2*i] + nand_reg[2*i+1];
    end
    for (i = 0; i < 16; i = i + 1) begin : gen_s2
        assign sum_stage2[i] = sum_stage1[2*i] + sum_stage1[2*i+1];
    end
    for (i = 0; i < 8; i = i + 1) begin : gen_s3
        assign sum_stage3[i] = sum_stage2[2*i] + sum_stage2[2*i+1];
    end
    for (i = 0; i < 4; i = i + 1) begin : gen_s4
        assign sum_stage4[i] = sum_stage3[2*i] + sum_stage3[2*i+1];
    end
    for (i = 0; i < 2; i = i + 1) begin : gen_s5
        assign sum_stage5[i] = sum_stage4[2*i] + sum_stage4[2*i+1];
    end
endgenerate

assign sum_final = sum_stage5[0] + sum_stage5[1];

// Lấy 6 bit kết quả phù hợp từ tổng cây gộp
assign eout = sum_final[5:0];

endmodule
```

### Phân tích kiến trúc vi mạch (Teacher CoT):
1. **Chức năng và Giao tiếp (I/O):**
   - Module `mdu_top` là một Đơn vị Nhân-Chia (Multiply-Divide Unit - MDU) tuần tự, nhận hai toán hạng 32-bit (`i_mdu_rs1`, `i_mdu_rs2`), mã lệnh 3-bit (`i_mdu_op`), và tín hiệu điều khiển `i_mdu_valid`.
   - Đầu ra gồm `o_mdu_ready` (báo rảnh/hoàn thành) và `o_mdu_rd` (kết quả 32-bit).

2. **Cấu trúc FSM và Datapath:**
   - Để tối ưu hóa diện tích và tài nguyên phần cứng, MDU sử dụng cơ chế tính toán tuần tự (iterative) hoặc tổ hợp có đăng ký (ở mức cơ bản cho kiến trúc chuẩn, ta thiết kế FSM 3 trạng thái: `IDLE`, `CALC`, `DONE`).
   - Các phép toán hỗ trợ qua `i_mdu_op`: Nhân (Low/High signed/unsigned), Chia (signed/unsigned), và Lấy dư (signed/unsigned).
   - Sử dụng các thanh ghi nội bộ để lưu trữ trạng thái, bộ đếm chu kỳ (nếu cần cho chia tuần tự), và các tín hiệu trung gian để tránh hoàn toàn *Inferred Latch* và *Race Condition*.

3. **Chống Latch & Race Condition:**
   - Mọi khối `always` tổ hợp đều gán đầy đủ giá trị cho mọi nhánh (`default` cho `case`, `else` cho `if`).
   - Mọi khối tuần tự dùng `posedge i_clk` và `posedge i_rst` với reset không đồng bộ tích cực mức cao (`i_rst`).

---

```verilog
module mdu_top (
    input  wire        i_clk,
    input  wire        i_rst,
    input  wire [31:0] i_mdu_rs1,
    input  wire [31:0] i_mdu_rs2,
    input  wire [2:0]  i_mdu_op,
    input  wire        i_mdu_valid,
    output reg         o_mdu_ready,
    output reg  [31:0] o_mdu_rd
);

    // Định nghĩa các trạng thái FSM
    parameter S_IDLE = 2'b00;
    parameter S_CALC = 2'b01;
    parameter S_DONE = 2'b10;

    reg [1:0] state_reg, state_next;
    reg [31:0] rd_reg, rd_next;
    reg ready_reg, ready_next;

    // FSM State Register
    always @(posedge i_clk or posedge i_rst) begin
        if (i_rst) begin
            state_reg <= S_IDLE;
            rd_reg    <= 32'd0;
            ready_reg <= 1'b1;
        end else begin
            state_reg <= state_next;
            rd_reg    <= rd_next;
            ready_reg <= ready_next;
        end
    end

    // FSM Combinational Logic
    always @(*) begin
        state_next = state_reg;
        rd_next    = rd_reg;
        ready_next = ready_reg;

        // Biến trung gian cho phép tính nhân/chia
        // i_mdu_op encoding ví dụ: 
        // 3'b000: MUL, 3'b001: MULH, 3'b010: MULHSU, 3'b011: MULHU
        // 3'b100: DIV, 3'b101: DIVU, 3'b110: REM, 3'b111: REMU

        casex (state_reg)
            S_IDLE: begin
                ready_next = 1'b1;
                if (i_mdu_valid) begin
                    ready_next = 1'b0;
                    state_next = S_CALC;

                    // Thực hiện phép tính tổ hợp trong 1 chu kỳ (đơn giản hóa MDU cho FPGA fabric)
                    casex (i_mdu_op)
                        3'b000: begin // MUL (Low 32-bit of signed * signed)
                            rd_next = $signed(i_mdu_rs1) * $signed(i_mdu_rs2);
                        end
                        3'b001: begin // MULH (High 32-bit of signed * signed)
                            rd_next = ($signed({i_mdu_rs1[31], i_mdu_rs1}) * $signed({i_mdu_rs2[31], i_mdu_rs2})) >> 32;
                        end
                        3'b010: begin // MULHSU (High 32-bit of signed * unsigned)
                            rd_next = ($signed({i_mdu_rs1[31], i_mdu_rs1}) * $signed({1'b0, i_mdu_rs2})) >> 32;
                        end
                        3'b011: begin // MULHU (High 32-bit of unsigned * unsigned)
                            rd_next = ({1'b0, i_mdu_rs1} * {1'b0, i_mdu_rs2}) >> 32;
                        end
                        3'b100: begin // DIV
                            if (i_mdu_rs2 == 32'd0)
                                rd_next = 32'hFFFFFFFF;
                            else if (i_mdu_rs1 == 32'h80000000 && i_mdu_rs2 == 32'hFFFFFFFF)
                                rd_next = 32'h80000000;
                            else
                                rd_next = $signed(i_mdu_rs1) / $signed(i_mdu_rs2);
                        end
                        3'b101: begin // DIVU
                            if (i_mdu_rs2 == 32'd0)
                                rd_next = 32'hFFFFFFFF;
                            else
                                rd_next = i_mdu_rs1 / i_mdu_rs2;
                        end
                        3'b110: begin // REM
                            if (i_mdu_rs2 == 32'd0)
                                rd_next = i_mdu_rs1;
                            else if (i_mdu_rs1 == 32'h80000000 && i_mdu_rs2 == 32'hFFFFFFFF)
                                rd_next = 32'd0;
                            else
                                rd_next = $signed(i_mdu_rs1) % $signed(i_mdu_rs2);
                        end
                        3'b111: begin // REMU
                            if (i_mdu_rs2 == 32'd0)
                                rd_next = i_mdu_rs1;
                            else
                                rd_next = i_mdu_rs1 % i_mdu_rs2;
                        end
                        default: begin
                            rd_next = 32'd0;
                        end
                    endcase
                end
            end

            S_CALC: begin
                state_next = S_DONE;
                ready_next = 1'b0;
            end

            S_DONE: begin
                state_next = S_IDLE;
                ready_next = 1'b1;
            end

            default: begin
                state_next = S_IDLE;
                ready_next = 1'b1;
                rd_next    = 32'd0;
            end
        endcase
    end

    // Output assignments
    always @(*) begin
        o_mdu_ready = ready_reg;
        o_mdu_rd    = rd_reg;
    end

endmodule
```

### Phân tích kiến trúc vi mạch (Teacher CoT):
1. **Phân tích lỗi cú pháp (Syntax Error):**
   - Trong mã nguồn trước, đoạn `p0 = in1 ^ in2;` bị viết nhầm bên ngoài khối `always` hoặc ngoài câu lệnh `assign`, gây ra lỗi cú pháp `syntax error, unexpected '=', expecting IDENTIFIER or TYPE_IDENTIFIER` tại dòng 11 trong ModelSim.
   - Các biến trung gian trong logic tổ hợp phải được khai báo bằng `wire` và gán bằng `assign`, hoặc khai báo bằng `reg` và gán trong khối `always @(*)`.
2. **Kiến trúc Kogge-Stone Adder 16-bit:**
   - **Level 0 (Generate & Propagate ban đầu):** 
     - $G_0 = A \cdot B$
     - $P_0 = A \oplus B$
   - **Các tầng tính toán carry (Stages 1, 2, 3, 4 tương ứng offset 1, 2, 4, 8):** Sử dụng các khối Black/Gray cell được mô tả gọn gàng qua vòng lặp `for` trong khối tổ hợp `always @(*)` hoặc kết hợp các lệnh `assign` liên tục để tạo ra mạng lưới song song chuẩn xác.
   - **Tính toán kết quả Sum và Cout:**
     - $Sum = P_0 \oplus C_{in}$ (với $C_{in} = 0$ cho bit thấp nhất, và $C[i] = G_{final}[i-1]$).
     - $C_{out} = G_{final}[15]$.
3. **Triệt tiêu Latch và Race Condition:**
   - Đảm bảo mọi biến trung gian trong `always @(*)` đều được gán giá trị cho mọi nhánh, sử dụng cú pháp gán blocking (`=`).
   - Tương thích hoàn toàn chuẩn IEEE 1364-2001 (không dùng SystemVerilog).

---

```verilog
module kogge_stone_16 (
    input  [15:0] in1,
    input  [15:0] in2,
    output [15:0] sum,
    output        cout
);

    // Level 0: Generate and Propagate
    wire [15:0] G0;
    wire [15:0] P0;

    assign G0 = in1 & in2;
    assign P0 = in1 ^ in2;

    // Khai báo các tín hiệu qua các stage của Kogge-Stone adder
    reg [15:0] g_st1, p_st1;
    reg [15:0] g_st2, p_st2;
    reg [15:0] g_st3, p_st3;
    reg [15:0] g_st4;
    reg [15:0] carries;

    integer j;
    always @(*) begin
        // Stage 1 (offset = 1)
        for (j = 0; j < 16; j = j + 1) begin
            if (j < 1) begin
                g_st1[j] = G0[j];
                p_st1[j] = P0[j];
            end else begin
                g_st1[j] = G0[j] | (P0[j] & G0[j-1]);
                p_st1[j] = P0[j] & P0[j-1];
            end
        end

        // Stage 2 (offset = 2)
        for (j = 0; j < 16; j = j + 1) begin
            if (j < 2) begin
                g_st2[j] = g_st1[j];
                p_st2[j] = p_st1[j];
            end else begin
                g_st2[j] = g_st1[j] | (p_st1[j] & g_st1[j-2]);
                p_st2[j] = p_st1[j] & p_st1[j-2];
            end
        end

        // Stage 3 (offset = 4)
        for (j = 0; j < 16; j = j + 1) begin
            if (j < 4) begin
                g_st3[j] = g_st2[j];
                p_st3[j] = p_st2[j];
            end else begin
                g_st3[j] = g_st2[j] | (p_st2[j] & g_st2[j-4]);
                p_st3[j] = p_st2[j] & p_st2[j-4];
            end
        end

        // Stage 4 (offset = 8)
        for (j = 0; j < 16; j = j + 1) begin
            if (j < 8) begin
                g_st4[j] = g_st3[j];
            end else begin
                g_st4[j] = g_st3[j] | (p_st3[j] & g_st3[j-8]);
            end
        end

        // Carries computation: C[i] = g_st4[i-1], C[0] = 0
        carries[0] = 1'b0;
        for (j = 1; j < 16; j = j + 1) begin
            carries[j] = g_st4[j-1];
        end
    end

    // Gán đầu ra cuối cùng
    assign sum  = P0 ^ carries;
    assign cout = g_st4[15];

endmodule
```

### Phân tích kiến trúc vi mạch (Teacher CoT):
1. **Chức năng và Giao tiếp I/O:**
   - Module `tlm_rx_data_snk_pwr_mgmt` giải mã các gói tin quản lý nguồn (Power Management) của PCIe dựa trên mã thông điệp (`msgcode_i`) khi có tín hiệu `ismsg_i` hợp lệ.
