    input  wire        reset_i,
    input  wire        ismsg_i,
    input  wire [7:0]  msgcode_i,
    input  wire [9:0]  pwr_data_i,
    input  wire        eval_pwr_mgmt_i,
    input  wire        eval_pwr_mgmt_data_i,
    input  wire        act_pwr_mgmt_i,
