### Phần 2: Mã Verilog chuẩn IEEE 1364-2001:

```verilog
// VerilogDB Combinational Logic Designs | Module: bm_1
// IEEE 1364-2001 Compliant

module bm_1 (
    input  [3:0] q,
    input  [3:0] m,
    output [7:0] R
);

    // Sử dụng trực tiếp q và m với việc mở rộng dấu tường minh 
    // để triệt tiêu hoàn toàn lỗi DANGLING_INPUT.
    wire signed [7:0] extended_q;
    wire signed [7:0] extended_m;

    // Gán giá trị tường minh từ input vào các wire trung gian có dấu
    assign extended_q = {{4{q[3]}}, q};
    assign extended_m = {{4{m[3]}}, m};

    // Thực hiện phép nhân có dấu 4-bit (cho ra kết quả 8-bit)
    // q và m được sử dụng 100% qua extended_q và extended_m.
    assign R = extended_q * extended_m;

endmodule
