### Mã nguồn Verilog (IEEE 1364-2001)

```verilog
module sig_change (
    input  wire clk,
    input  wire reset,
    input  wire d,
    output reg  toggle,
    output reg  fall,
    output reg  rise
);

    // Thanh ghi lưu trữ giá trị của d ở chu kỳ trước
    reg d_reg;

    always @(posedge clk) begin
        if (reset) begin
            d_reg  <= 1'b0;
            toggle <= 1'b0;
            fall   <= 1'b0;
            rise   <= 1'b0;
        end else begin
            // Cập nhật giá trị trước đó
            d_reg  <= d;

            // Phát hiện thay đổi và các loại sườn xung
            toggle <= (d_reg != d);
            rise   <= (~d_reg & d);
            fall   <= (d_reg & ~d);
        end
    end

endmodule
```

