```verilog
module demux_1x4 (
    input  wire       a,
    input  wire [1:0] s,
    output reg  [3:0] y
);

    // Triển khai Demultiplexer 1-to-4 sử dụng logic tổ hợp thuần túy
    // Phù hợp với đặc tả sử dụng cổng NOT và AND (mô tả bằng hành vi chuẩn Verilog-2001)
    always @(*) begin
        // Mặc định gán toàn bộ ngõ ra bằng 0 để tránh Inferred Latch
        y = 4'b0000;

        casex (s)
            2'b00: y[0] = a;
            2'b01: y[1] = a;
            2'b10: y[2] = a;
            2'b11: y[3] = a;
            default: y = 4'b0000;
        endcase
    end

endmodule
