module arithmetic_operations_optimized (
    input  [31:0] A,
    input  [31:0] B,
    input  [31:0] C,
    input  [31:0] D,
    input  [31:0] E,
    input  [31:0] F,
    input  [31:0] G,
    input  [31:0] H,
    output [31:0] result1,
    output [31:0] result2,
    output [31:0] result3
);

    // Khai báo các tín hiệu trung gian để tối ưu hóa và dễ đọc
    wire [31:0] sum_ab;
    wire [31:0] prod_cd;
    wire [31:0] sub_ef;

    // Thực hiện các phép toán cơ bản
    assign sum_ab  = A + B;
    assign prod_cd = C * D;
    assign sub_ef  = E - F;

    // Tính toán các kết quả đầu ra theo đặc tả
    assign result1 = sum_ab + prod_cd;
    assign result2 = prod_cd + sub_ef;
    assign result3 = sum_ab + G + H;

endmodule
```

### Phân tích kiến trúc vi mạch (Teacher CoT):
1. **Chức năng I/O & Độ rộng bit:**
   - Đầu vào: `A` (1-bit), `B` (1-bit).
   - Đầu ra: `AeB` (A bằng B, 1-bit), `AgB` (A lớn hơn B, 1-bit), `AlB` (A nhỏ hơn B, 1-bit).
2. **Cấu trúc logic:**
   - Đây là mạch tổ hợp thuần túy thực hiện so sánh hai số 1-bit.
   - Theo đặc tả, sử dụng cấu trúc `case` trong khối `always @(*)` để so sánh ghép cặp `{A, B}`:
     - `2'b00`: A = 0, B = 0 $\rightarrow$ `AeB = 1`, `AgB = 0`, `AlB = 0`
     - `2'b01`: A = 0, B = 1 $\rightarrow$ `AeB = 0`, `AgB = 0`, `AlB = 1`
     - `2'b10`: A = 1, B = 0 $\rightarrow$ `AeB = 0`, `AgB = 1`, `AlB = 0`
     - `2'b11`: A = 1, B = 1 $\rightarrow$ `AeB = 1`, `AgB = 0`, `AlB = 0`
3. **Triệt tiêu Latch & Race Condition:**
   - Sử dụng đầy đủ các nhánh trong lệnh `case` và gán giá trị mặc định cho tất cả các đầu ra trước khối `case` (hoặc dùng nhánh `default`) để tránh sinh chốt ẩn (Inferred Latch).
   - Dùng phép gán blocking `=` bên trong khối tổ hợp `always @(*)`.

```verilog
module comparator1bit (
    input  wire A,
    input  wire B,
    output reg  AeB,
    output reg  AgB,
    output reg  AlB
);

    always @(*) begin
        // Gán mặc định để tránh chốt ẩn (inferred latches)
        AeB = 1'b0;
        AgB = 1'b0;
        AlB = 1'b0;

        case ({A, B})
            2'b00: begin
                AeB = 1'b1;
                AgB = 1'b0;
                AlB = 1'b0;
            end
            2'b01: begin
                AeB = 1'b0;
                AgB = 1'b0;
                AlB = 1'b1;
            end
            2'b10: begin
                AeB = 1'b0;
                AgB = 1'b1;
                AlB = 1'b0;
            end
            2'b11: begin
                AeB = 1'b1;
                AgB = 1'b0;
                AlB = 1'b0;
            end
            default: begin
                AeB = 1'b0;
                AgB = 1'b0;
                AlB = 1'b0;
            end
        endcase
    end

endmodule
```

