// Target: sky130_fd_sc_hd__and4b (Adapted to available ports)

module sky130_fd_sc_hd__and4b (
    input  wire A_N,
    input  wire C,
    input  wire D,
    output wire X
);

    // Combinational logic: 
    // Implementing the logic function based on available inputs:
    // X = (NOT A_N) AND C AND D
    assign X = (~A_N) & C & D;

