module sky130_fd_sc_hd__nor2 (
    input  wire A,
    output wire Y
);

    // Internal representation of the logic described:
    // Inverting A -> ~A
    // Combining with internal pull-up / power-good (treated as 1'b1 for this pinout)
    // Here we implement the logical equivalent for the 1-input visible wrapper:
    // Y = ~A (acting as the specified inverted path buffering to Y)

    assign Y = ~A;

endmodule
