```verilog
module mux_81 (
    input  wire D0,
    input  wire D1,
    input  wire D2,
    input  wire D3,
    input  wire D4,
    input  wire D5,
    input  wire D6,
    input  wire D7,
    input  wire S0,
    input  wire S1,
    input  wire S2,
    output reg  out
);

    // Ghép các tín hiệu chọn thành bus 3-bit: {S2, S1, S0}
    wire [2:0] sel;
    assign sel = {S2, S1, S0};

    always @(*) begin
        case (sel)
            3'b000:  out = D0;
            3'b001:  out = D1;
            3'b010:  out = D2;
            3'b011:  out = D3;
            3'b100:  out = D4;
            3'b101:  out = D5;
            3'b110:  out = D6;
            3'b111:  out = D7;
            default: out = 1'b0;
        endcase
    end

endmodule
```

