---

```verilog
// Verilog-2001 Synthesizable Implementation
// Target: ModelSim-Altera & Quartus II 13.0sp1

module sbox4 (
    input  wire [1:0] addr,
    output reg  [1:0] dout
);

    // Combinational logic implementing a 2-to-2 bit S-Box substitution table
    always @(*) begin
        case (addr)
            2'b00:   dout = 2'b10;
            2'b01:   dout = 2'b11;
            2'b10:   dout = 2'b01;
            2'b11:   dout = 2'b00;
            default: dout = 2'b00;
        endcase
    end

endmodule
```

