    input  A1,
    input  A2,
    input  A3,
    input  B1,
    input  C1
);

    // Logic function: O311A standard cell 
    // X = ((A1 & A2 & A3) | B1 | C1)

    reg x_comb;

    always @(*) begin
        x_comb = ((A1 & A2 & A3) | B1 | C1);
    end

