                    sclk    <= 1'b0;
                    cs_n    <= 1'b1;
                    busy    <= 1'b0;
                    rx_data <= shift_rx;
                    state   <= IDLE;
                end
                default: state <= IDLE;
            endcase
        end
    end
endmodule
