                    state <= 3'b011;
                end
                else begin
                    state <= 3'b000;
                end
                data_out <= 1'b1;
            end
            3'b011: begin
                if (~data_in) begin
                    state <= 3'b100;
                end
                else begin
                    state <= 3'b011;
                end
                data_out <= 1'b0;
