        if (cnt2 == (NUM_DIV / 2) - 1)
            clk_div2 <= ~clk_div2;
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        clk_div <= 1'b0;
    else
        clk_div <= clk_div1 | clk_div2;
end

